package com.smartcoms.hms.entity;
import jakarta.persistence.*; import java.time.*;
@Entity public class Appointment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String patientName; private String doctor; private String department; private LocalDate date; private LocalTime time; private String status="Confirmed"; public Long getId(){return id;} public String getPatientName(){return patientName;} public void setPatientName(String v){patientName=v;} public String getDoctor(){return doctor;} public void setDoctor(String v){doctor=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public LocalDate getDate(){return date;} public void setDate(LocalDate v){date=v;} public LocalTime getTime(){return time;} public void setTime(LocalTime v){time=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
